Answer: \begin{align}
u \times v
    &= \begin{bmatrix}
        i  &  j  &  k \\
       u_1 & u_2 & u_3 \\
       v_1 & v_2 & v_3 \\
    \end{bmatrix} \\
    &= \begin{bmatrix}
        u_2v_3 - u_3v_2 \\ u_3v_1 - u_1v_3 \\ u_1v_2 - u_2v_1 \\
    \end{bmatrix} \\
    &=\begin{bmatrix}
          0 & -u_3 &  u_2 \\
        u_3 &    0 & -u_1 \\
       -u_2 &  u_1 &  0 \\
    \end{bmatrix}
    \begin{bmatrix}
        v_1 \\ v_2 \\ v_3 \\
    \end{bmatrix} \\
\end{align} 
